-- =====================================================================
-- ECollect | Supabase setup 4 of 4: Barangay Poblacion data
-- Copied from the MySQL database "solidwaste_scheduling" on 19 Oct 2026 22:50 by supabase/tools/mysql_to_supabase.py
-- Run ONCE, after 01-03, on an empty project. Logins are not copied (see the setup guide).
-- =====================================================================
begin;
set local ecollect.allow_zone_change = 'on';   -- the 10 zones are inserted once, here

-- barangay_admin: 1 row(s)

-- lgu_admin: 1 row(s)

-- truck: 2 row(s)

-- route: 10 row(s)

-- waste_category: 2 row(s)

-- garbage_collector: 1 row(s)

-- resident: 0 row(s)

-- collection_point: 6 row(s)

-- collection_point_zone: 9 row(s) (Mon/Wed/Fri: Kim Guan = Zones 5-6, Sapporo = Zones 1-2)

-- collection_schedule: 19 row(s)

-- pickup_log: 0 row(s)

-- location_history: 0 row(s)

-- announcement: 2 row(s)

-- feedback_report: 0 row(s)

-- emergency_collection: 0 row(s)

-- reports: 0 row(s)

-- Continue numbering after the imported rows.
select setval(pg_get_serial_sequence('public.barangay_admin', 'barangay_admin_id'), greatest(coalesce((select max(barangay_admin_id) from public.barangay_admin), 0), 1), (select count(*) > 0 from public.barangay_admin));
select setval(pg_get_serial_sequence('public.lgu_admin', 'lgu_admin_id'), greatest(coalesce((select max(lgu_admin_id) from public.lgu_admin), 0), 1), (select count(*) > 0 from public.lgu_admin));
select setval(pg_get_serial_sequence('public.truck', 'truck_id'), greatest(coalesce((select max(truck_id) from public.truck), 0), 1), (select count(*) > 0 from public.truck));
select setval(pg_get_serial_sequence('public.route', 'route_id'), greatest(coalesce((select max(route_id) from public.route), 0), 1), (select count(*) > 0 from public.route));
select setval(pg_get_serial_sequence('public.waste_category', 'waste_category_id'), greatest(coalesce((select max(waste_category_id) from public.waste_category), 0), 1), (select count(*) > 0 from public.waste_category));
select setval(pg_get_serial_sequence('public.garbage_collector', 'garbage_collector_id'), greatest(coalesce((select max(garbage_collector_id) from public.garbage_collector), 0), 1), (select count(*) > 0 from public.garbage_collector));
select setval(pg_get_serial_sequence('public.resident', 'resident_id'), greatest(coalesce((select max(resident_id) from public.resident), 0), 1), (select count(*) > 0 from public.resident));
select setval(pg_get_serial_sequence('public.collection_point', 'collection_point_id'), greatest(coalesce((select max(collection_point_id) from public.collection_point), 0), 1), (select count(*) > 0 from public.collection_point));
select setval(pg_get_serial_sequence('public.collection_schedule', 'collection_schedule_id'), greatest(coalesce((select max(collection_schedule_id) from public.collection_schedule), 0), 1), (select count(*) > 0 from public.collection_schedule));
select setval(pg_get_serial_sequence('public.pickup_log', 'pickup_log_id'), greatest(coalesce((select max(pickup_log_id) from public.pickup_log), 0), 1), (select count(*) > 0 from public.pickup_log));
select setval(pg_get_serial_sequence('public.location_history', 'location_history_id'), greatest(coalesce((select max(location_history_id) from public.location_history), 0), 1), (select count(*) > 0 from public.location_history));
select setval(pg_get_serial_sequence('public.announcement', 'announcement_id'), greatest(coalesce((select max(announcement_id) from public.announcement), 0), 1), (select count(*) > 0 from public.announcement));
select setval(pg_get_serial_sequence('public.feedback_report', 'feedback_report_id'), greatest(coalesce((select max(feedback_report_id) from public.feedback_report), 0), 1), (select count(*) > 0 from public.feedback_report));
select setval(pg_get_serial_sequence('public.emergency_collection', 'emergency_collection_id'), greatest(coalesce((select max(emergency_collection_id) from public.emergency_collection), 0), 1), (select count(*) > 0 from public.emergency_collection));
select setval(pg_get_serial_sequence('public.reports', 'report_id'), greatest(coalesce((select max(report_id) from public.reports), 0), 1), (select count(*) > 0 from public.reports));

-- Zone days/times and the fixed schedule follow the truck stops (Kim Guan 5:00-5:30 Zones 5-6, Sapporo 5:30-6:00 Zones 1-2)
select public.fs_sync();

commit;

-- Check: should list Zone 1 ... Zone 10.
select route_id, zone_name, collection_days, start_time, end_time, collection_mode from public.route order by route_id;
